actions.action:
// No nexus - no filing required
apportionment.state_tax = 0.0;
apportionment.state_refund_or_owed = apportionment.state_payments;

            // Calculate NJ state additions
            double additions = 0.0;

            // NJ adds back interest on U.S. government obligations
            // (exempt from federal tax but taxable to NJ)
            // additions += revenue.federal_bond_interest;

            // NJ adds back IRC 199A deduction (state doesn't conform)
            // additions += result.section_199a_deduction;

            // NJ may require depreciation adjustments
            // additions += result.nj_depreciation_addback;

            apportionment.state_additions = additions;

            // Calculate NJ state subtractions
            double subtractions = 0.0;

            // NJ allows subtraction for interest on NJ government bonds
            // subtractions += revenue.nj_municipal_interest;

            // NJ NOL deduction (different rules from federal)
            // subtractions += result.nj_nol_deduction;

            apportionment.state_subtractions = subtractions;

            // Store NJ entire net income for surtax calculation
            result.nj_entire_net_income = apportionment.state_taxable_income;

            // NJ uses 9% base rate (NJ Rev. Stat. § 54:10A-5)
            // Additional 2.5% surtax applies to income > $1M (table 50490)
            apportionment.state_tax =
              apportionment.state_taxable_income * apportionment.state_tax_rate;

            // Subtract NJ state credits
            apportionment.state_tax =
              Math.max(0.0, apportionment.state_tax - apportionment.state_credits);

            // Surtax will be added in table 50490 if income > $1M
            // For now, calculate base refund/owed (will be adjusted by surtax)
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;

            // NJ surtax is 2.5% of entire net income for income > $1M
            result.nj_surtax =
              result.nj_entire_net_income * result.nj_surtax_rate;

            // Add surtax to total state tax
            apportionment.state_tax = apportionment.state_tax + result.nj_surtax;

            // Recalculate refund or amount owed including surtax
            apportionment.state_refund_or_owed =
              apportionment.state_payments - apportionment.state_tax;
